CREATE TABLE public.finance_reconciliation_explanations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),month_start date NOT NULL,reconciliation_key text NOT NULL,snapshot text NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.finance_reconciliation_explanations TO authenticated;
GRANT ALL ON public.finance_reconciliation_explanations TO service_role;
ALTER TABLE public.finance_reconciliation_explanations ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_explanation_read ON public.finance_reconciliation_explanations FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE INDEX ON public.finance_reconciliation_explanations(tenant_id,month_start,reconciliation_key);
CREATE OR REPLACE FUNCTION public.finance_reconciliation_rows(p_tenant uuid,p_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE m date:=date_trunc('month',p_month)::date; cutoff date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date; result jsonb; BEGIN
IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT (public.is_tenant_admin(p_tenant,auth.uid()) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Finance administrator required'; END IF;
WITH gl AS (SELECT a.id,a.code,a.name,coalesce(sum(CASE WHEN e.id IS NOT NULL THEN l.debit-l.credit ELSE 0 END),0) balance FROM public.chart_of_accounts a LEFT JOIN public.journal_lines l ON l.account_id=a.id AND l.tenant_id=p_tenant LEFT JOIN public.journal_entries e ON e.id=l.entry_id AND e.tenant_id=p_tenant AND e.status='posted' AND e.entry_date<=cutoff WHERE a.tenant_id=p_tenant GROUP BY a.id),
supplier_items AS (
SELECT 'invoice:'||i.id id,coalesce(s.name,'Supplier')||' · '||coalesce(i.invoice_number,'Invoice') name,i.invoice_date date,greatest(i.total_amount-coalesce(i.amount_paid,0),0) amount,'/procurement/finance/suppliers/'||i.supplier_id href FROM public.invoices i LEFT JOIN public.suppliers s ON s.id=i.supplier_id WHERE i.tenant_id=p_tenant AND i.invoice_date<=cutoff AND coalesce(i.review_status,'') NOT IN ('Draft','Voided') AND i.payment_status IS DISTINCT FROM 'voided'
UNION ALL SELECT 'bill:'||b.id,coalesce(b.vendor_name,'Bill')||' · '||coalesce(b.bill_number,'Bill'),b.bill_date,greatest(b.total_amount-coalesce(b.paid_amount,0),0),'/expenses/bills?bill='||b.id FROM public.expense_bills b JOIN public.journal_entries e ON e.id=b.journal_entry_id AND e.status='posted' WHERE b.tenant_id=p_tenant AND b.bill_date<=cutoff AND b.approval_status='posted'),
payroll_items AS (SELECT p.id,concat_ws(' ',h.first_name,h.last_name) name,make_date(p.year,p.month,1) date,greatest(coalesce(p.net_salary,0)-coalesce(p.salary_paid_amount,0),0) salary,greatest(coalesce(p.mpf_employee,0)+coalesce(p.mpf_employer,0)-coalesce(p.mpf_paid_amount,0),0) mpf FROM public.hr_payroll p JOIN public.journal_entries e ON e.id=p.accrual_journal_entry_id AND e.status='posted' LEFT JOIN public.hr_employees h ON h.id=p.employee_id WHERE p.tenant_id=p_tenant AND make_date(p.year,p.month,1)<=cutoff),
customer_items AS (SELECT id,customer_name||' · '||coalesce(invoice_no,'Contract') name,invoice_date date,outstanding_amount amount,'/finance/receivables' href FROM public.customer_opening_balances WHERE tenant_id=p_tenant AND invoice_date<=cutoff AND NOT is_credit_note AND outstanding_amount>0),
pending_batches AS (SELECT b.*,concat_ws(' · ',p.name,mer.display_name) name FROM public.payment_settlement_batches b JOIN public.payment_processors p ON p.id=b.processor_id LEFT JOIN public.payment_processor_merchants mer ON mer.id=b.merchant_id LEFT JOIN public.bank_transactions t ON t.id=b.bank_transaction_id WHERE b.tenant_id=p_tenant AND b.transaction_date<=cutoff AND NOT(coalesce(t.status,'') IN ('matched','cleared','posted') AND coalesce(t.match_confidence,'')<>'low' AND (t.matched_record_id IS NOT NULL OR t.journal_entry_id IS NOT NULL))),
base AS (
SELECT 'supplier' key,'Supplier ledger' name,coalesce((SELECT -sum(balance) FROM gl WHERE code IN ('2010','2100')),0) books,coalesce((SELECT sum(amount) FROM supplier_items),0) detail,'Unpaid purchase invoices + posted bills · recorded balances' note,coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'date',date,'amount',amount,'href',href) ORDER BY id) FROM supplier_items WHERE amount>0),'[]'::jsonb) items,'open' setup
UNION ALL SELECT 'salary','Salary payable',coalesce((SELECT -sum(balance) FROM gl WHERE code='2040'),0),coalesce((SELECT sum(salary) FROM payroll_items),0),'Payroll net unpaid · recorded balances',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'date',date,'amount',salary,'href','/hr/payroll') ORDER BY id) FROM payroll_items WHERE salary>0),'[]'::jsonb),'open'
UNION ALL SELECT 'mpf','MPF payable',coalesce((SELECT -sum(balance) FROM gl WHERE code='2030'),0),coalesce((SELECT sum(mpf) FROM payroll_items),0),'MPF unpaid · recorded balances',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'date',date,'amount',mpf,'href','/hr/payroll') ORDER BY id) FROM payroll_items WHERE mpf>0),'[]'::jsonb),'open'
UNION ALL SELECT 'customer','Customer ledger',coalesce((SELECT sum(balance) FROM gl WHERE code='1120'),0),coalesce((SELECT sum(amount) FROM customer_items),0),'Open contract receivables · no inferred Arca contract',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY id) FROM customer_items c),'[]'::jsonb),'open'
UNION ALL SELECT 'cards','Card processors',coalesce((SELECT sum(balance) FROM gl WHERE code IN ('1290','1295')),0),coalesce((SELECT sum(net_settlement) FROM pending_batches),0),'Unmatched settlement batches due · latest statement '||coalesce((SELECT max(transaction_date)::text FROM public.payment_settlement_batches WHERE tenant_id=p_tenant AND transaction_date<=cutoff),'not loaded'),coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'date',transaction_date,'amount',net_settlement,'href','/finance/receivables?view=payouts') ORDER BY id) FROM pending_batches),'[]'::jsonb),CASE WHEN EXISTS(SELECT 1 FROM public.payment_settlement_batches WHERE tenant_id=p_tenant AND transaction_date>=m AND transaction_date<=cutoff) THEN 'open' ELSE 'missing' END
UNION ALL SELECT 'bank:'||a.id,'Bank · '||a.account_name,coalesce(g.balance,0),coalesce(s.closing_balance,0),CASE WHEN s.period_end>=m THEN 'Statement to '||s.period_end::text ELSE 'No statement since '||coalesce(s.period_end::text,'not loaded') END,jsonb_build_array(jsonb_build_object('id',a.id,'name',a.account_name||' · '||a.currency,'date',s.period_end,'amount',s.closing_balance,'href','/finance/cash?view=close')),CASE WHEN a.linked_gl_account_id IS NULL THEN 'set up' WHEN s.period_end>=m THEN 'open' ELSE 'missing' END FROM public.bank_accounts a LEFT JOIN gl g ON g.id=a.linked_gl_account_id LEFT JOIN LATERAL(SELECT * FROM public.bank_statement_imports WHERE tenant_id=p_tenant AND bank_account_id=a.id AND period_end<=cutoff ORDER BY period_end DESC LIMIT 1)s ON true WHERE a.tenant_id=p_tenant AND a.is_active AND a.account_name !~* '^test( |$)'
UNION ALL SELECT 'stock','Stock',NULL::numeric,NULL::numeric,'Not in the books yet','[]'::jsonb,'set up'),
signed AS (SELECT *,round(detail-books,2) difference,md5(jsonb_build_array(key,books,detail,note,items)::text) snapshot FROM base)
SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'name',name,'books',books,'detail',detail,'difference',difference,'note',note,'items',items,'snapshot',snapshot,'state',CASE WHEN setup='set up' THEN 'set up' WHEN setup='open' AND abs(difference)<0.005 THEN 'agrees' ELSE 'open' END,'reason',(SELECT reason FROM public.finance_reconciliation_explanations ex WHERE ex.tenant_id=p_tenant AND ex.month_start=m AND ex.reconciliation_key=signed.key AND ex.snapshot=signed.snapshot ORDER BY created_at DESC LIMIT 1))), '[]'::jsonb) INTO result FROM signed;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.finance_reconciliation_rows(uuid,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.finance_reconciliation_rows(uuid,date) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.finance_explain_reconciliation(p_tenant uuid,p_month date,p_key text,p_snapshot text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r jsonb; m date:=date_trunc('month',p_month)::date; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('finance-period:'||p_tenant::text,0));
SELECT x INTO r FROM jsonb_array_elements(public.finance_reconciliation_rows(p_tenant,m)) x WHERE x->>'key'=p_key;
IF r IS NULL OR r->>'snapshot' IS DISTINCT FROM p_snapshot THEN RAISE EXCEPTION 'Reconciliation changed; refresh and review again'; END IF;
IF r->>'state'<>'open' THEN RAISE EXCEPTION 'Only open reconciliations need an explanation'; END IF;
INSERT INTO public.finance_reconciliation_explanations(tenant_id,month_start,reconciliation_key,snapshot,reason,created_by) VALUES(p_tenant,m,p_key,p_snapshot,btrim(p_reason),auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.finance_explain_reconciliation(uuid,date,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.finance_explain_reconciliation(uuid,date,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_close_reconciliation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE rows jsonb; BEGIN
IF NEW.reopened_at IS NULL THEN
rows:=public.finance_reconciliation_rows(NEW.tenant_id,NEW.month_start);
IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'state'='open' AND nullif(r->>'reason','') IS NULL) THEN RAISE EXCEPTION 'Reconciliations must agree or be explained'; END IF;
IF EXISTS(SELECT 1 FROM public.bank_transactions t WHERE t.tenant_id=NEW.tenant_id AND date_trunc('month',t.txn_date)::date=NEW.month_start AND NOT(coalesce(t.status,'') IN ('matched','cleared','posted') AND coalesce(t.match_confidence,'')<>'low' AND (t.matched_record_id IS NOT NULL OR t.journal_entry_id IS NOT NULL))) OR NOT EXISTS(SELECT 1 FROM public.payment_settlement_batches b WHERE b.tenant_id=NEW.tenant_id AND date_trunc('month',b.transaction_date)::date=NEW.month_start) OR EXISTS(SELECT 1 FROM public.payment_settlement_batches b LEFT JOIN public.bank_transactions t ON t.id=b.bank_transaction_id WHERE b.tenant_id=NEW.tenant_id AND date_trunc('month',b.transaction_date)::date=NEW.month_start AND NOT(coalesce(t.status,'') IN ('matched','cleared','posted') AND coalesce(t.match_confidence,'')<>'low' AND (t.matched_record_id IS NOT NULL OR t.journal_entry_id IS NOT NULL))) THEN RAISE EXCEPTION 'Open bank or card matching exceptions remain'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER finance_close_reconciliations BEFORE INSERT OR UPDATE ON public.finance_closed_periods FOR EACH ROW EXECUTE FUNCTION public.finance_close_reconciliation_guard();